+#[inline]
+fn pz1050_read_varint(b: &[u8], i: &mut usize) -> u64 {
+    let mut v = 0u64;
+    let mut s = 0u32;
+    loop {
+        let byte = b[*i];
+        *i += 1;
+        v |= ((byte & 0x7f) as u64) << s;
+        if byte & 0x80 == 0 {
+            break;
+        }
+        s += 7;
+    }
+    v
+}
